import React from 'react';
import { calcWriteBackLoaderForApp } from '../../molecules/write-back-loader';
import './index.less';
import { InjectedApplication } from '@/hub/types/application';
import { UI } from '@/deprecated/types';

export type WriteBackOverlayProps = {
  showLoadingWidget: boolean;
  loadingWidgetId?: string;
  application?: InjectedApplication;
  hubPosition: UI.HubPosition;
};

export const WriteBackOverlay = React.forwardRef<HTMLDivElement, WriteBackOverlayProps>(
  ({ showLoadingWidget, loadingWidgetId, application, hubPosition }, ref) => {
    const Loader = calcWriteBackLoaderForApp(loadingWidgetId?.toString());

    return (
      <>
        {showLoadingWidget ? <Loader application={application} hubPosition={hubPosition} /> : null}
        <div ref={ref} className="overlay" />
      </>
    );
  },
);

WriteBackOverlay.displayName = 'WriteBackOverlay';
